async def act(page):
    # Navigate directly to the order view for order #125 (relative goto)
    await page.goto("/index.php/admin/sales_order/view/order_id/125/")
    await page.wait_for_load_state("networkidle")
    await page.wait_for_timeout(800)

    # Try to find a Shipping Address group and open its Edit UI (prefer group-scoped Edit)
    shipping_group = None
    try:
        groups = page.get_by_role("group").filter(has=page.get_by_text("Shipping Address"))
        if await groups.count() > 0:
            shipping_group = groups.first
            if await shipping_group.get_by_role("link", name="Edit").count() > 0:
                await shipping_group.get_by_role("link", name="Edit").first.click()
                await page.wait_for_timeout(700)
        else:
            # fallback: click a page-level Edit link if present
            if await page.get_by_role("link", name="Edit").count() > 0:
                await page.get_by_role("link", name="Edit").first.click()
                await page.wait_for_timeout(700)
    except Exception:
        # best-effort continue
        pass

    # Choose parent scope for fills: prefer shipping_group when available
    parent = shipping_group if shipping_group is not None else page

    # Fill Street lines (prefer two separate inputs, otherwise newline in single field)
    try:
        filled = False
        for lbl in ["Street", "Street Address", "Street 1", "Address Line 1"]:
            if await parent.get_by_label(lbl).count() > 0:
                el = parent.get_by_label(lbl)
                cnt = await el.count()
                if cnt >= 2:
                    await el.nth(0).fill("654 Elm Drive")
                    await el.nth(1).fill("Apartment 12")
                else:
                    await el.first.fill("654 Elm Drive
Apartment 12")
                filled = True
                break
        if not filled:
            if await parent.get_by_role("textbox").count() > 0:
                tb = parent.get_by_role("textbox")
                if await tb.count() >= 2:
                    await tb.nth(0).fill("654 Elm Drive")
                    await tb.nth(1).fill("Apartment 12")
                else:
                    await tb.first.fill("654 Elm Drive
Apartment 12")
    except Exception:
        pass

    # City
    try:
        for lbl in ["City", "Town/City"]:
            if await parent.get_by_label(lbl).count() > 0:
                await parent.get_by_label(lbl).first.fill("Miami")
                break
    except Exception:
        pass

    # Postal code / ZIP
    try:
        for lbl in ["Zip/Postal Code", "Postcode", "ZIP/Postal Code", "ZIP", "Zip"]:
            if await parent.get_by_label(lbl).count() > 0:
                await parent.get_by_label(lbl).first.fill("33101")
                break
    except Exception:
        pass

    # Region / State - prefer select_option, fallback to fill abbreviation
    try:
        region_done = False
        for lbl in ["State/Province", "State", "Region"]:
