                reg = parent.get_by_label(lbl).first
                try:
                    await reg.select_option(label="Florida")
                    region_done = True
                    break
                except Exception:
                    try:
                        await reg.select_option(value="FL")
                        region_done = True
                        break
                    except Exception:
                        try:
                            await reg.fill("FL")
                            region_done = True
                            break
                        except Exception:
                            pass
        if not region_done and await parent.get_by_role("combobox").count() > 0:
            cb = parent.get_by_role("combobox").first
            try:
                await cb.select_option(label="Florida")
            except Exception:
                try:
                    await cb.select_option(value="FL")
                except Exception:
                    pass
    except Exception:
        pass

    # Country - prefer selecting United States
    try:
        for lbl in ["Country", "Country/Region"]:
            if await parent.get_by_label(lbl).count() > 0:
                country = parent.get_by_label(lbl).first
                try:
                    await country.select_option(label="United States")
                except Exception:
                    try:
