                    except Exception:
                        try:
                            await country.select_option(value="US")
                        except Exception:
                            pass
                break
    except Exception:
        pass

    # Telephone (optional) - fill if present and empty
    try:
        for lbl in ["Telephone", "Phone"]:
            if await parent.get_by_label(lbl).count() > 0:
                phone = parent.get_by_label(lbl).first
                try:
                    val = await phone.input_value()
                except Exception:
                    val = None
                try:
                    if val in (None, ""):
                        await phone.fill("3050000000")
                except Exception:
                    try:
                        await phone.fill("3050000000")
                    except Exception:
                        pass
                break
    except Exception:
        pass

    # Save the updated address. Prefer a button scoped inside the Shipping Address group (full path).
    try:
